<div class="d-flex mb-3"><h2 class="h4">卡密批次</h2><a class="btn btn-primary ms-auto" href="<?= h(url_to('admin/card/generate')) ?>">生成批次</a></div><div class="table-responsive table-card"><table class="table"><thead><tr><th>ID</th><th>名称</th><th>面值</th><th>数量</th><th>前缀</th><th>过期</th><th>操作</th></tr></thead><tbody><?php foreach ($list as $r): ?><tr><td><?= h($r['id']) ?></td><td><?= h($r['name']) ?></td><td><?= h(money($r['face_value'])) ?></td><td><?= h($r['qty']) ?></td><td><?= h($r['prefix']) ?></td><td><?= h($r['expire_time'] ? fmt_time($r['expire_time']) : '永久') ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= h(url_to('admin/card/cards', ['id' => $r['id']])) ?>">卡密列表</a> <a class="btn btn-sm btn-outline-success" href="<?= h(url_to('admin/card/export', ['id' => $r['id']])) ?>">导出 CSV</a><form class="d-inline" method="post" action="<?= h(url_to('admin/card/disable')) ?>"><?= csrf_field() ?><input type="hidden" name="batch_id" value="<?= h($r['id']) ?>"><button class="btn btn-sm btn-outline-secondary">停用</button></form><form class="d-inline" method="post" action="<?= h(url_to('admin/card/delete')) ?>"><?= csrf_field() ?><input type="hidden" name="batch_id" value="<?= h($r['id']) ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="确定删除未使用卡密？">删除</button></form></td></tr><?php endforeach; ?></tbody></table></div>